1	import { useEffect, useState } from "react";
2	import { useParams, useLocation } from "wouter";
3	import { Layout } from "@/components/layout";
4	import { BackButton } from "@/components/back-button";
5	import {
6	  CheckCircle2, Calendar, Clock, MapPin, Phone, Mail,
7	  User, CreditCard, Loader2, XCircle, ExternalLink, Download,
8	  Users, Copy, Check, ChevronDown,
9	} from "lucide-react";
10	import { getSportLabel } from "@/components/sport-icon";
11	import { Button } from "@/components/ui/button";
12	import {
13	  DropdownMenu,
14	  DropdownMenuContent,
15	  DropdownMenuItem,
16	  DropdownMenuTrigger,
17	} from "@/components/ui/dropdown-menu";
18	import { Badge } from "@/components/ui/badge";
19	import { Separator } from "@/components/ui/separator";
20	import { format } from "date-fns";
21	import { lt } from "date-fns/locale";
22	
23	const BASE = import.meta.env.BASE_URL.replace(/\/$/, "");
24	const API = `${BASE}/api`;
25	
26	interface BookingDetail {
27	  id: number;
28	  courtId: number;
29	  courtName?: string;
30	  courtSport?: string;
31	  facilityName?: string;
32	  courtAddress?: string;
33	  courtCity?: string;
34	  customerName: string;
35	  customerEmail: string;
36	  customerPhone?: string | null;
37	  date: string;
38	  startTime: string;
39	  endTime: string;
40	  totalPrice: number;
41	  status: "pending" | "confirmed" | "cancelled" | "awaiting_players";
42	  stripeSessionId?: string | null;
43	  createdAt: string;
44	  isSplit?: boolean;
45	  totalSlots?: number;
46	  pricePerSlot?: number;
47	  splitInviteToken?: string | null;
48	}
49	
50	interface SplitParticipant {
51	  userId: string;
52	  userName: string | null;
53	  userEmail: string | null;
54	  paymentStatus: string;
55	  joinedAt: string;
56	}
57	
58	interface SplitStatus {
59	  bookingId: number;
60	  gameId: number | null;
61	  bookingStatus: string;
62	  totalSlots: number;
63	  pricePerSlot: number;
64	  totalPrice: number;
65	  shareToken: string | null;
66	  participants: SplitParticipant[];
67	}
68	
69	interface CourtDetail {
70	  id: number;
71	  name: string;
72	  address: string;
73	  city: string;
74	  phone?: string | null;
75	  ownerEmail?: string | null;
76	  imageUrl?: string | null;
77	  type: string;
78	}
79	
80	function formatDate(value: string): string {
81	  const d = new Date(value);
82	  return Number.isNaN(d.getTime()) ? value : format(d, "yyyy-MM-dd");
83	}
84	
85	function formatDateLong(value: string): string {
86	  const d = new Date(value);
87	  return Number.isNaN(d.getTime()) ? value : format(d, "EEEE, yyyy-MM-dd", { locale: lt });
88	}
89	
90	function StatusBadge({ status }: { status: string }) {
91	  switch (status) {
92	    case "confirmed":
93	      return <Badge className="bg-green-500 text-white"><CheckCircle2 className="w-3 h-3 mr-1" />Patvirtinta</Badge>;
94	    case "pending":
95	      return <Badge variant="secondary" className="bg-yellow-500/20 text-yellow-700 dark:text-yellow-400"><Clock className="w-3 h-3 mr-1" />Laukiama</Badge>;
96	    case "awaiting_players":
97	      return <Badge variant="secondary" className="bg-blue-500/20 text-blue-700 dark:text-blue-400"><Users className="w-3 h-3 mr-1" />Laukiama žaidėjų</Badge>;
98	    case "cancelled":
99	      return <Badge variant="destructive"><XCircle className="w-3 h-3 mr-1" />Atšaukta</Badge>;
100	    default:
101	      return <Badge variant="outline">{status}</Badge>;
102	  }
103	}
104	
105	export default function BookingDetail() {
106	  const { id } = useParams<{ id: string }>();
107	  const [, setLocation] = useLocation();
108	  const [booking, setBooking] = useState<BookingDetail | null>(null);
109	  const [court, setCourt] = useState<CourtDetail | null>(null);
110	  const [splitStatus, setSplitStatus] = useState<SplitStatus | null>(null);
111	  const [loading, setLoading] = useState(true);
112	  const [error, setError] = useState<string | null>(null);
113	  const [copied, setCopied] = useState(false);
114	
115	  useEffect(() => {
116	    const load = async () => {
117	      try {
118	        const bookingRes = await fetch(`${API}/bookings/${id}`);
119	        if (!bookingRes.ok) throw new Error("Rezervacija nerasta");
120	        const bookingData = await bookingRes.json();
121	        setBooking(bookingData);
122	
123	        const [courtResult, splitResult] = await Promise.allSettled([
124	          bookingData.courtId
125	            ? fetch(`${API}/courts/${bookingData.courtId}`).then(r => r.ok ? r.json() : null)
126	            : Promise.resolve(null),
127	          bookingData.isSplit
128	            ? fetch(`${API}/bookings/${bookingData.id}/split-status`).then(r => r.ok ? r.json() : null)
129	            : Promise.resolve(null),
130	        ]);
131	
132	        if (courtResult.status === "fulfilled" && courtResult.value) {
133	          setCourt(courtResult.value);
134	        }
135	        if (splitResult.status === "fulfilled" && splitResult.value) {
136	          setSplitStatus(splitResult.value);
137	        }
138	      } catch (err: any) {
139	        setError(err.message ?? "Klaida");
140	      } finally {
141	        setLoading(false);
142	      }
143	    };
144	    load();
145	  }, [id]);
146	
147	  const shareUrl = splitStatus?.shareToken
148	    ? `${window.location.origin}${BASE}/join/${splitStatus.shareToken}`
149	    : null;
150	
151	  const handleCopyLink = async () => {
152	    if (!shareUrl) return;
153	    try {
154	      await navigator.clipboard.writeText(shareUrl);
155	      setCopied(true);
156	      setTimeout(() => setCopied(false), 2000);
157	    } catch {
158	      // fallback: select text
159	    }
160	  };
161	
162	  if (loading) {
163	    return (
164	      <Layout>
165	        <div className="container flex items-center justify-center min-h-[60vh]">
166	          <Loader2 className="w-8 h-8 animate-spin text-primary" />
167	        </div>
168	      </Layout>
169	    );
170	  }
171	
172	  if (error || !booking) {
173	    return (
174	      <Layout>
175	        <div className="container flex flex-col items-center justify-center min-h-[60vh] gap-4">
176	          <XCircle className="w-12 h-12 text-destructive" />
177	          <p className="text-lg font-medium">{error ?? "Rezervacija nerasta"}</p>
178	          <BackButton to="/bookings" label="Grįžti" />
179	        </div>
180	      </Layout>
181	    );
182	  }
183	
184	  const courtName = booking.courtName ?? court?.name ?? `Kortas #${booking.courtId}`;
185	  const address = court ? `${court.address}, ${court.city}` : null;
186	  const phone = court?.phone ?? null;
187	  const email = court?.ownerEmail ?? null;
188	  const duration = (() => {
189	    const [sh, sm] = booking.startTime.split(":").map(Number);
190	    const [eh, em] = booking.endTime.split(":").map(Number);
191	    const mins = (eh * 60 + em) - (sh * 60 + (sm ?? 0));
192	    const h = Math.floor(mins / 60);
193	    const m = mins % 60;
194	    return m > 0 ? `${h}h ${m}min` : `${h}h`;
195	  })();
196	
197	  return (
198	    <Layout>
199	      <div className="container mx-auto px-4 py-8 max-w-lg">
200	        {/* Back button */}
201	        <BackButton to="/bookings" label="Visos rezervacijos" />
202	
203	        {/* Header */}
204	        <div className="flex items-start justify-between gap-3 mb-6">
205	          <div>
206	            <h1 className="text-xl font-bold">Rezervacija #{booking.id}</h1>
207	            <p className="text-sm text-muted-foreground mt-0.5">{courtName}</p>
208	          </div>
209	          <StatusBadge status={booking.status} />
210	        </div>
211	
212	        {/* Court image */}
213	        {court?.imageUrl && (
214	          <div className="rounded-xl overflow-hidden mb-5 h-40 bg-muted">
215	            <img
216	              src={court.imageUrl.startsWith("http") ? court.imageUrl : `${BASE}/${court.imageUrl}`}
217	              alt={courtName}
218	              className="w-full h-full object-cover"
219	            />
220	          </div>
221	        )}
222	
223	        {/* Booking info card */}
224	        <div className="bg-card border rounded-xl divide-y divide-border overflow-hidden mb-4">
225	          <div className="px-4 py-3 flex items-center gap-3">
226	            <Calendar className="w-4 h-4 text-muted-foreground shrink-0" />
227	            <div>
228	              <p className="text-xs text-muted-foreground">Data</p>
229	              <p className="text-sm font-medium capitalize">{formatDateLong(booking.date)}</p>
230	            </div>
231	          </div>
232	          <div className="px-4 py-3 flex items-center gap-3">
233	            <Clock className="w-4 h-4 text-muted-foreground shrink-0" />
234	            <div>
235	              <p className="text-xs text-muted-foreground">Laikas</p>
236	              <p className="text-sm font-medium">{booking.startTime} – {booking.endTime} <span className="text-muted-foreground font-normal">({duration})</span></p>
237	            </div>
238	          </div>
239	          <div className="px-4 py-3 flex items-center gap-3">
240	            <CreditCard className="w-4 h-4 text-muted-foreground shrink-0" />
241	            <div>
242	              <p className="text-xs text-muted-foreground">
243	                {booking.isSplit
244	                  ? "Jūsų mokėjimo dalis"
245	                  : booking.status === "confirmed" ? "Sumokėta" : "Kaina"}
246	              </p>
247	              <p className="text-sm font-medium">
248	                {booking.isSplit && booking.pricePerSlot != null
249	                  ? (booking.pricePerSlot > 0 ? `€${Number(booking.pricePerSlot).toFixed(2)}` : "Nemokama")
250	                  : (booking.totalPrice > 0 ? `€${Number(booking.totalPrice).toFixed(2)}` : "Nemokama")}
251	              </p>
252	              {booking.isSplit && booking.pricePerSlot != null && (
253	                <p className="text-xs text-muted-foreground">Visa kaina: €{Number(booking.totalPrice).toFixed(2)}</p>
254	              )}
255	            </div>
256	          </div>
257	          <div className="px-4 py-3 flex items-center gap-3">
258	            <User className="w-4 h-4 text-muted-foreground shrink-0" />
259	            <div>
260	              <p className="text-xs text-muted-foreground">Rezervavo</p>
261	              <p className="text-sm font-medium">{booking.customerName}</p>
262	            </div>
263	          </div>
264	        </div>
265	
266	        {/* Split payment progress panel */}
267	        {booking.isSplit && splitStatus && (
268	          <div className="bg-card border rounded-xl overflow-hidden mb-4">
269	            <div className="px-4 py-3 flex items-center justify-between border-b">
270	              <div className="flex items-center gap-2">
271	                <Users className="w-4 h-4 text-blue-600 dark:text-blue-400" />
272	                <p className="text-sm font-semibold">Bendras mokėjimas</p>
273	              </div>
274	              <Badge variant="secondary" className="bg-blue-500/20 text-blue-700 dark:text-blue-400 text-xs">
275	                {splitStatus.participants.filter(p => p.paymentStatus === "paid").length}/{splitStatus.totalSlots} apmokėta
276	              </Badge>
277	            </div>
278	
279	            {/* Progress bar */}
280	            <div className="px-4 pt-3 pb-1">
281	              <div className="w-full bg-muted rounded-full h-2 overflow-hidden">
282	                <div
283	                  className="h-2 rounded-full bg-blue-500 transition-all"
284	                  style={{ width: `${Math.round((splitStatus.participants.filter(p => p.paymentStatus === "paid").length / splitStatus.totalSlots) * 100)}%` }}
285	                />
286	              </div>
287	            </div>
288	
289	            {/* Slot dots */}
290	            <div className="px-4 pt-2 pb-3 flex gap-1.5 flex-wrap">
291	              {Array.from({ length: splitStatus.totalSlots }).map((_, i) => {
292	                const paid = splitStatus.participants.filter(p => p.paymentStatus === "paid");
293	                const isPaid = i < paid.length;
294	                return (
295	                  <div
296	                    key={i}
297	                    className={`w-8 h-8 rounded-lg border-2 flex items-center justify-center text-xs font-bold ${
298	                      isPaid
299	                        ? "bg-blue-500 border-blue-500 text-white"
300	                        : "bg-muted border-border text-muted-foreground"
301	                    }`}
302	                  >
303	                    {isPaid ? "✓" : i + 1}
304	                  </div>
305	                );
306	              })}
307	            </div>
308	
309	            <Separator />
310	
311	            {/* Participant list */}
312	            {splitStatus.participants.length > 0 && (
313	              <div className="px-4 py-3 space-y-2">
314	                <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">Žaidėjai</p>
315	                {splitStatus.participants.map((p, i) => (
316	                  <div key={i} className="flex items-center justify-between gap-2 text-sm">
317	                    <div className="min-w-0">
318	                      <p className="truncate font-medium">{p.userName ?? p.userEmail ?? `Žaidėjas ${i + 1}`}</p>
319	                      {p.userEmail && p.userName && (
320	                        <p className="truncate text-xs text-muted-foreground">{p.userEmail}</p>
321	                      )}
322	                    </div>
323	                    {p.paymentStatus === "paid"
324	                      ? <Badge className="bg-green-500/20 text-green-700 dark:text-green-400 border-0 text-xs shrink-0">Sumokėta</Badge>
325	                      : <Badge variant="secondary" className="text-xs shrink-0">Laukiama</Badge>}
326	                  </div>
327	                ))}
328	              </div>
329	            )}
330	
331	            {/* Share link (only if still awaiting players) */}
332	            {shareUrl && booking.status === "awaiting_players" && (
333	              <>
334	                <Separator />
335	                <div className="px-4 py-3 space-y-2">
336	                  <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Kvietimo nuoroda</p>
337	                  <p className="text-xs text-muted-foreground">Pasidalinkite su žaidėjais, kad jie galėtų sumokėti savo dalį.</p>
338	                  <div className="flex gap-2">
339	                    <code className="flex-1 text-xs bg-muted rounded-lg px-3 py-2 truncate font-mono">{shareUrl}</code>
340	                    <Button size="sm" variant="outline" className="shrink-0 gap-1.5" onClick={handleCopyLink}>
341	                      {copied ? <Check className="w-3.5 h-3.5 text-green-600" /> : <Copy className="w-3.5 h-3.5" />}
342	                      {copied ? "Nukopijuota" : "Kopijuoti"}
343	                    </Button>
344	                  </div>
345	                </div>
346	              </>
347	            )}
348	          </div>
349	        )}
350	
351	        {/* Court contact info */}
352	        {(address || phone || email) && (
353	          <div className="bg-card border rounded-xl divide-y divide-border overflow-hidden mb-4">
354	            <div className="px-4 py-2.5">
355	              <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Aikštelės kontaktai</p>
356	            </div>
357	            {address && (
358	              <div className="px-4 py-3 flex items-center gap-3">
359	                <MapPin className="w-4 h-4 text-muted-foreground shrink-0" />
360	                <div className="flex-1 min-w-0">
361	                  <p className="text-sm">{address}</p>
362	                </div>
363	                <a
364	                  href={`https://maps.google.com/?q=${encodeURIComponent(address)}`}
365	                  target="_blank"
366	                  rel="noopener noreferrer"
367	                  className="text-primary hover:text-primary/80 shrink-0"
368	                  onClick={e => e.stopPropagation()}
369	                >
370	                  <ExternalLink className="w-4 h-4" />
371	                </a>
372	              </div>
373	            )}
374	            {phone && (
375	              <div className="px-4 py-3 flex items-center gap-3">
376	                <Phone className="w-4 h-4 text-muted-foreground shrink-0" />
377	                <a href={`tel:${phone}`} className="text-sm hover:text-primary transition-colors">{phone}</a>
378	              </div>
379	            )}
380	            {email && (
381	              <div className="px-4 py-3 flex items-center gap-3">
382	                <Mail className="w-4 h-4 text-muted-foreground shrink-0" />
383	                <a href={`mailto:${email}`} className="text-sm hover:text-primary transition-colors truncate">{email}</a>
384	              </div>
385	            )}
386	          </div>
387	        )}
388	
389	        {/* Court link + calendar */}
390	        <div className="flex gap-3">
391	          <Button
392	            variant="outline"
393	            className="flex-1"
394	            onClick={() => setLocation(`/courts/${booking.courtId}`)}
395	          >
396	            <ExternalLink className="w-4 h-4 mr-2" />
397	            Aikštelės puslapis
398	          </Button>
399	          <DropdownMenu>
400	            <DropdownMenuTrigger asChild>
401	              <Button variant="outline" className="flex-1">
402	                <Calendar className="w-4 h-4 mr-2" />
403	                Pridėti į kalendorių
404	                <ChevronDown className="w-4 h-4 ml-2" />
405	              </Button>
406	            </DropdownMenuTrigger>
407	            <DropdownMenuContent align="end">
408	              <DropdownMenuItem onClick={() => {
409	                const date = booking.date.replace(/-/g, "");
410	                const start = date + "T" + booking.startTime.slice(0, 5).replace(":", "") + "00";
411	                const end = date + "T" + booking.endTime.slice(0, 5).replace(":", "") + "00";
412	                const sportLabel = getSportLabel(booking.courtSport);
413	                const courtLabel = booking.courtName ?? "Kortas";
414	                const title = booking.facilityName
415	                  ? `${sportLabel} – ${courtLabel}, ${booking.facilityName}`
416	                  : `${sportLabel} – ${courtLabel}`;
417	                const addressParts = [
418	                  booking.courtAddress,
419	                  booking.courtCity,
420	                  "Lietuva",
421	                ].filter(Boolean);
422	                const location = addressParts.join(", ");
423	                const siteUrl = "https://korts.lt";
424	                const bookingUrl = `${siteUrl}/bookings/${booking.id}`;
425	                const details = [
426	                  `📅 Rezervacija #${booking.id}`,
427	                  `🏟 Aikštelė: ${courtLabel}`,
428	                  booking.facilityName ? `🏢 Objektas: ${booking.facilityName}` : null,
429	                  `⚽ Sportas: ${sportLabel}`,
430	                  `💶 Kaina: ${Number(booking.totalPrice).toFixed(2)} €`,
431	                  `🔗 Peržiūrėti: ${bookingUrl}`,
432	                ].filter(Boolean).join("\n");
433	                const url =
434	                  `https://calendar.google.com/calendar/render?action=TEMPLATE` +
435	                  `&text=${encodeURIComponent(title)}` +
436	                  `&dates=${start}/${end}` +
437	                  `&ctz=Europe%2FVilnius` +
438	                  `&details=${encodeURIComponent(details)}` +
439	                  `&location=${encodeURIComponent(location)}`;
440	                window.open(url, "_blank");
441	              }}>
442	                <img src="https://ssl.gstatic.com/calendar/images/dynamiclogo_2020q4/calendar_31_2x.png" className="w-4 h-4 mr-2 object-contain" alt="" />
443	                Google Calendar
444	              </DropdownMenuItem>
445	              <DropdownMenuItem onClick={() => window.open(`${API}/bookings/${booking.id}/ics`, "_blank")}>
446	                <Download className="w-4 h-4 mr-2" />
447	                Apple Calendar (.ics)
448	              </DropdownMenuItem>
449	            </DropdownMenuContent>
450	          </DropdownMenu>
451	        </div>
452	      </div>
453	    </Layout>
454	  );
455	}
