454	export default function Bookings() {
455	  const t = useT();
456	  const [tab, setTab] = useState<"upcoming" | "past">("upcoming");
457	  const [sortKey, setSortKey] = useState<SortKey>("dateAsc");
458	  const [splitOnly, setSplitOnly] = useState(false);
459	  const [ratingBooking, setRatingBooking] = useState<{
460	    id: number; courtName?: string; courtId: number; customerName: string;
461	  } | null>(null);
462	  const [cancelTargetId, setCancelTargetId] = useState<number | null>(null);
463	
464	  const { data: bookings, isLoading } = useListBookings({});
465	  const cancelBooking = useCancelBooking();
466	  const queryClient = useQueryClient();
467	  const { toast } = useToast();
468	
469	  const handleCancelConfirmed = async (id: number) => {
470	    try {
471	      const result = await cancelBooking.mutateAsync({ id });
472	      const refunded = Number((result as any)?.refundAmount ?? 0);
473	      toast({
474	        title: t("bookings.status.cancelled"),
475	        description: refunded > 0
476	          ? t("bookings.cancel.toastRefunded").replace("{amount}", refunded.toFixed(2))
477	          : t("bookings.cancel.toastNoRefund"),
478	      });
479	      queryClient.invalidateQueries({ queryKey: getListBookingsQueryKey() });
480	      queryClient.invalidateQueries({ queryKey: ["court-activity"] });
481	      queryClient.invalidateQueries({
482	        predicate: (q) => Array.isArray(q.queryKey) && q.queryKey.some(
483	          (k) => typeof k === "string" && k.includes("/availability"),
484	        ),
485	      });
486	    } catch {
487	      toast({ title: "Klaida", variant: "destructive" });
488	    }
489	  };
490	
491	  const today = new Date();
492	  today.setHours(0, 0, 0, 0);
493	
494	  const sorted = (bookings ?? []).slice().sort((a, b) => {
495	    if (sortKey === "createdDesc" || sortKey === "createdAsc") {
496	      const ca = a.createdAt ? new Date(a.createdAt).getTime() : 0;
497	      const cb = b.createdAt ? new Date(b.createdAt).getTime() : 0;
498	      return sortKey === "createdDesc" ? cb - ca : ca - cb;
499	    }
500	    const da = new Date(a.date).getTime();
501	    const db2 = new Date(b.date).getTime();
502	    if (da !== db2) return sortKey === "dateAsc" ? da - db2 : db2 - da;
503	    return sortKey === "dateAsc"
504	      ? a.startTime.localeCompare(b.startTime)
505	      : b.startTime.localeCompare(a.startTime);
506	  });
507	
508	  const localCancelledIds: number[] = (() => {
509	    try { return JSON.parse(sessionStorage.getItem("cancelledBookingIds") ?? "[]"); } catch { return []; }
510	  })();
511	  const startMs = (b: typeof sorted[number]) => {
512	    const dt = new Date(b.date);
513	    const [hh, mm] = (b.endTime ?? b.startTime ?? "00:00").split(":").map(Number);
514	    dt.setHours(hh || 0, mm || 0, 0, 0);
515	    return dt.getTime();
516	  };
517	  const nowMs = Date.now();
518	  const upcomingBookings = sorted.filter(b => {
519	    return startMs(b) > nowMs && b.status !== "cancelled" && !localCancelledIds.includes(b.id);
520	  });
521	
522	  const pastBookings = sorted.filter(b => {
523	    return startMs(b) <= nowMs || b.status === "cancelled";
524	  });
525	
526	  const allDisplayed = tab === "upcoming" ? upcomingBookings : pastBookings;
527	  const displayed = splitOnly ? allDisplayed.filter(b => (b as any).isSplit) : allDisplayed;
528	
529	  return (
530	    <Layout>
531	      <div className="container mx-auto px-4 py-8 max-w-2xl">
